// Python-value semantics used by the loader/dumper:
//  - ordered map with Python dict key equality (1 == 1.0 == True, etc.)
//  - date / datetime wrappers with Python str()/isoformat() rendering
//  - CPython repr() for floats
//  - Python-style comparison used by sorted(mapping) in the representer

export class PyDate {
  constructor(year, month, day) {
    this.kind = 'date';
    this.year = year; this.month = month; this.day = day;
  }
  isoformat() {
    return `${pad(this.year, 4)}-${pad(this.month, 2)}-${pad(this.day, 2)}`;
  }
  toString() { return this.isoformat(); }
}

export class PyDateTime {
  // tzOffsetMin: null for naive, otherwise offset minutes east of UTC.
  constructor(year, month, day, hour, minute, second, microsecond, tzOffsetMin) {
    this.kind = 'datetime';
    this.year = year; this.month = month; this.day = day;
    this.hour = hour; this.minute = minute; this.second = second;
    this.microsecond = microsecond;
    this.tzOffsetMin = tzOffsetMin;
  }
  isoformat(sep = ' ') {
    let s = `${pad(this.year, 4)}-${pad(this.month, 2)}-${pad(this.day, 2)}${sep}` +
      `${pad(this.hour, 2)}:${pad(this.minute, 2)}:${pad(this.second, 2)}`;
    if (this.microsecond) s += '.' + pad(this.microsecond, 6);
    if (this.tzOffsetMin !== null && this.tzOffsetMin !== undefined) {
      const off = this.tzOffsetMin;
      const sign = off < 0 ? '-' : '+';
      const a = Math.abs(off);
      s += `${sign}${pad(Math.floor(a / 60), 2)}:${pad(a % 60, 2)}`;
    }
    return s;
  }
  toString() { return this.isoformat(' '); }
}

function pad(n, w) {
  let s = String(n);
  while (s.length < w) s = '0' + s;
  return s;
}

// Ordered map with Python dict semantics.
export class PyMap {
  constructor() {
    this.entries = [];      // [[key, value], ...] insertion ordered
    this.index = new Map(); // canonical hash key -> entry index
  }
  set(key, value) {
    const hk = pyHashKey(key);
    if (hk !== null && this.index.has(hk)) {
      this.entries[this.index.get(hk)][1] = value;
    } else {
      if (hk !== null) this.index.set(hk, this.entries.length);
      this.entries.push([key, value]);
    }
  }
  get(key) {
    const hk = pyHashKey(key);
    if (hk !== null && this.index.has(hk)) return this.entries[this.index.get(hk)][1];
    return undefined;
  }
  has(key) {
    const hk = pyHashKey(key);
    return hk !== null && this.index.has(hk);
  }
  get size() { return this.entries.length; }
  [Symbol.iterator]() { return this.entries[Symbol.iterator](); }
}

// Set: insertion-ordered list of values (ordering only observable through
// sorting at dump time, so insertion order is a safe carrier).
export class PySet {
  constructor() {
    this.values = [];
    this.index = new Set();
  }
  add(v) {
    const hk = pyHashKey(v);
    if (hk === null || !this.index.has(hk)) {
      if (hk !== null) this.index.add(hk);
      this.values.push(v);
    }
  }
  get size() { return this.values.length; }
  [Symbol.iterator]() { return this.values[Symbol.iterator](); }
}

function isDate(v) { return v instanceof PyDate; }
function isDateTime(v) { return v instanceof PyDateTime; }

// Canonical hash key implementing Python's equality for dict keys.
export function pyHashKey(v) {
  if (v === null || v === undefined) return 'n:';
  if (typeof v === 'boolean') return 'i:' + (v ? '1' : '0');
  if (typeof v === 'bigint') return 'i:' + v.toString();
  if (typeof v === 'number') {
    if (Number.isNaN(v)) return 'f:nan:' + Math.random(); // NaN != NaN
    if (Number.isInteger(v) && Math.abs(v) < 2 ** 53) return 'i:' + String(v);
    if (v === 0) return 'i:0';
    return 'f:' + String(v);
  }
  if (typeof v === 'string') return 's:' + v;
  if (v instanceof Uint8Array) return 'b:' + Buffer.from(v).toString('base64');
  if (isDateTime(v)) {
    if (v.tzOffsetMin === null || v.tzOffsetMin === undefined) {
      return `dt:${v.year},${v.month},${v.day},${v.hour},${v.minute},${v.second},${v.microsecond}`;
    }
    return 'dt@' + (Date.UTC(v.year, v.month - 1, v.day, v.hour, v.minute, v.second) - v.tzOffsetMin * 60000) + '.' + v.microsecond;
  }
  if (isDate(v)) return `d:${v.year},${v.month},${v.day}`;
  return null; // unhashable (list, map, set) -> Python would raise TypeError
}

export function isHashable(v) {
  return pyHashKey(v) !== null;
}

// Python == for scalar keys.
export function pyEq(a, b) {
  if (a === b) {
    if (typeof a === 'number' && Number.isNaN(a)) return false;
    return true;
  }
  const na = numericValue(a), nb = numericValue(b);
  if (na !== null && nb !== null) {
    if (na.nan || nb.nan) return false;
    if (na.big !== null && nb.big !== null) return na.big === nb.big;
    return na.num === nb.num;
  }
  if (typeof a === 'string' && typeof b === 'string') return a === b;
  if (a instanceof Uint8Array && b instanceof Uint8Array) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
    return true;
  }
  if (isDateTime(a) && isDateTime(b)) {
    const ta = a.tzOffsetMin, tb = b.tzOffsetMin;
    if ((ta === null) !== (tb === null)) return false;
    if (ta === null) {
      return a.year === b.year && a.month === b.month && a.day === b.day &&
        a.hour === b.hour && a.minute === b.minute && a.second === b.second &&
        a.microsecond === b.microsecond;
    }
    return instantMicros(a) === instantMicros(b);
  }
  return false; // date vs datetime: not equal; other mismatches: not equal
}

function numericValue(v) {
  if (typeof v === 'boolean') return { big: BigInt(v ? 1 : 0), num: v ? 1 : 0, nan: false };
  if (typeof v === 'bigint') return { big: v, num: Number(v), nan: false };
  if (typeof v === 'number') {
    if (Number.isNaN(v)) return { big: null, num: NaN, nan: true };
    if (Number.isInteger(v) && Math.abs(v) < 2 ** 53) {
      return { big: BigInt(v), num: v, nan: false };
    }
    return { big: null, num: v, nan: false };
  }
  return null;
}

function instantMicros(dt) {
  return Date.UTC(dt.year, dt.month - 1, dt.day, dt.hour, dt.minute, dt.second) * 1000 +
    dt.microsecond - dt.tzOffsetMin * 60000000;
}

// Python < for sortable scalars. Throws TypeError-like Error when not
// comparable (mirrors sorted() raising TypeError).
export function pyCompare(a, b) {
  if (pyEq(a, b)) return 0;
  const na = numericValue(a), nb = numericValue(b);
  if (na !== null && nb !== null) {
    if (na.nan || nb.nan) {
      // CPython sorts NaN unpredictably vs numbers via <; treat as less.
      return na.nan ? -1 : 1;
    }
    if (na.big !== null && nb.big !== null) return na.big < nb.big ? -1 : 1;
    return na.num < nb.num ? -1 : 1;
  }
  if (typeof a === 'string' && typeof b === 'string') return codePointCompare(a, b);
  if (a instanceof Uint8Array && b instanceof Uint8Array) {
    const n = Math.min(a.length, b.length);
    for (let i = 0; i < n; i++) {
      if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
    }
    return a.length - b.length;
  }
  if (isDate(a) && isDate(b) && !isDateTime(a) && !isDateTime(b)) {
    return cmpNums([a.year, a.month, a.day], [b.year, b.month, b.day]);
  }
  if (isDateTime(a) && isDateTime(b)) {
    if ((a.tzOffsetMin === null) !== (b.tzOffsetMin === null)) {
      throw new TypeError_("can't compare offset-naive and offset-aware datetimes");
    }
    if (a.tzOffsetMin === null) {
      return cmpNums(
        [a.year, a.month, a.day, a.hour, a.minute, a.second, a.microsecond],
        [b.year, b.month, b.day, b.hour, b.minute, b.second, b.microsecond]);
    }
    const d = instantMicros(a) - instantMicros(b);
    return d < 0 ? -1 : d > 0 ? 1 : 0;
  }
  throw new TypeError_(`'<' not supported between instances of '${pyTypeName(b)}' and '${pyTypeName(a)}'`);
}

export class TypeError_ extends Error {
  constructor(msg) { super(msg); this.name = 'TypeError'; }
}

function pyTypeName(v) {
  if (v === null) return 'NoneType';
  if (typeof v === 'boolean') return 'bool';
  if (typeof v === 'bigint') return 'int';
  if (typeof v === 'number') return 'float';
  if (typeof v === 'string') return 'str';
  if (v instanceof Uint8Array) return 'bytes';
  if (isDateTime(v)) return 'datetime';
  if (isDate(v)) return 'date';
  if (Array.isArray(v)) return 'list';
  if (v instanceof PyMap) return 'dict';
  if (v instanceof PySet) return 'set';
  return 'object';
}

function cmpNums(a, b) {
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
  }
  return 0;
}

// Python str comparison: by Unicode code points.
function codePointCompare(a, b) {
  const ca = Array.from(a), cb = Array.from(b);
  const n = Math.min(ca.length, cb.length);
  for (let i = 0; i < n; i++) {
    const pa = ca[i].codePointAt(0), pb = cb[i].codePointAt(0);
    if (pa !== pb) return pa < pb ? -1 : 1;
  }
  const d = ca.length - cb.length;
  return d < 0 ? -1 : d > 0 ? 1 : 0;
}

// CPython repr() of a float.
export function pyFloatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';
  if (x === 0) return Object.is(x, -0) ? '-0.0' : '0.0';
  const sign = x < 0 ? '-' : '';
  const ax = Math.abs(x);
  // Shortest round-trip digits via toExponential().
  const exp = ax.toExponential(); // like "1.2345e+16" or "5e+0"
  const m = /^(\d)(?:\.(\d+))?e([+-]\d+)$/.exec(exp);
  let digits = m[1] + (m[2] || '');
  const e10 = parseInt(m[3], 10); // value = d.ddd * 10^e10
  const decpt = e10 + 1;          // position of decimal point
  if (decpt > -4 && decpt <= 16) {
    // fixed notation
    let out;
    if (decpt <= 0) {
      out = '0.' + '0'.repeat(-decpt) + digits;
    } else if (decpt >= digits.length) {
      out = digits + '0'.repeat(decpt - digits.length) + '.0';
    } else {
      out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
    }
    return sign + out;
  }
  // scientific notation
  let mant = digits[0];
  if (digits.length > 1) mant += '.' + digits.slice(1);
  const e = decpt - 1;
  const esign = e < 0 ? '-' : '+';
  let ed = String(Math.abs(e));
  if (ed.length < 2) ed = '0' + ed;
  return `${sign}${mant}e${esign}${ed}`;
}

// datetime validation (mirrors datetime.datetime constructor errors)
export function isValidDate(y, m, d) {
  if (m < 1 || m > 12) return false;
  if (d < 1 || d > daysInMonth(y, m)) return false;
  return y >= 1 && y <= 9999;
}

export function isValidTime(h, mi, s) {
  return h >= 0 && h <= 23 && mi >= 0 && mi <= 59 && s >= 0 && s <= 59;
}

function daysInMonth(y, m) {
  if (m === 2) return isLeap(y) ? 29 : 28;
  return [4, 6, 9, 11].includes(m) ? 30 : 31;
}

function isLeap(y) {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

